export interface CheckCaptureReceipt {
  status: 'done' | 'output-limit' | 'incomplete' | 'spawn-error';
  exitCode: number | null;
}

const RECEIPT = /^(?:\{"status":"done","exitCode":(\d{1,3}|null)\}|\{"status":"output-limit","exitCode":null\}|\{"status":"incomplete","exitCode":null\}|\{"status":"spawn-error","exitCode":null\})\n$/;

/** Parse only receipts generated by this trusted supervisor. */
export function parseCheckCaptureReceipt(value: string): CheckCaptureReceipt | null {
  const matched = RECEIPT.exec(value);
  if (!matched) return null;
  if (value.startsWith('{"status":"output-limit"')) return { status: 'output-limit', exitCode: null };
  if (value.startsWith('{"status":"incomplete"')) return { status: 'incomplete', exitCode: null };
  if (value.startsWith('{"status":"spawn-error"')) return { status: 'spawn-error', exitCode: null };
  const exitCode = matched[1] === 'null' ? null : Number(matched[1]);
  return exitCode === null || exitCode <= 255 ? { status: 'done', exitCode } : null;
}

/**
 * Detached trusted Node group leader. stdout is host-opened capture; fd 3 is
 * private receipt, never inherited by check. Parent kills group after receipt.
 */
export const CHECK_CAPTURE_SUPERVISOR = String.raw`
const { spawn } = require('node:child_process');
const { writeSync } = require('node:fs');
const [shell, command, limitText] = process.argv.slice(1);
const limit = Number(limitText);
const DRAIN_GRACE_MS = 100;
let settled = false;
let held = false;
const holdForParent = () => { if (!held) { held = true; setInterval(() => {}, 2 ** 31 - 1); } };
const writeAll = (fd, bytes) => {
  let offset = 0;
  try {
    while (offset < bytes.length) {
      const written = writeSync(fd, bytes, offset, bytes.length - offset);
      if (!Number.isInteger(written) || written <= 0) return false;
      offset += written;
    }
    return true;
  } catch { return false; }
};
const receipt = (status, exitCode) => {
  if (settled) return;
  settled = true;
  writeAll(3, Buffer.from(JSON.stringify({ status, exitCode }) + '\n'));
  holdForParent();
};
let child;
try { child = spawn(shell, ['-c', command], { stdio: ['ignore', 'pipe', 'pipe'], windowsHide: true }); }
catch { receipt('spawn-error', null); }
if (child) {
  let bytes = 0;
  let writeFailed = false;
  let exited = false;
  let exitCode = null;
  let stdoutEnded = false;
  let stderrEnded = false;
  let drainTimer;
const finish = () => {
    if (!exited || !stdoutEnded || !stderrEnded) return;
    if (drainTimer) clearTimeout(drainTimer);
    receipt(writeFailed ? 'spawn-error' : 'done', writeFailed ? null : exitCode);
  };
  const finishAfterGrace = () => {
    if (!exited) return;
    receipt(writeFailed ? 'spawn-error' : 'incomplete', null);
  };
  const capture = chunk => {
    if (settled) return;
    const allowed = Math.max(0, limit - bytes);
    if (allowed) {
      const output = chunk.subarray(0, allowed);
      if (writeAll(1, output)) bytes += output.length;
      else { writeFailed = true; receipt('spawn-error', null); }
    }
    if (bytes >= limit) receipt('output-limit', null);
  };
  child.stdout.on('data', capture);
  child.stderr.on('data', capture);
  child.stdout.once('end', () => { stdoutEnded = true; finish(); });
  child.stderr.once('end', () => { stderrEnded = true; finish(); });
  child.once('error', () => receipt('spawn-error', null));
  child.once('exit', code => {
    exited = true;
    exitCode = code;
    // Descendants may hold pipes forever. Drain currently buffered data, then
    // report direct-shell completion while group leader remains killable.
    drainTimer = setTimeout(finishAfterGrace, DRAIN_GRACE_MS);
    finish();
  });
}
`;
